def platform_backend(platform: str) -> Backend | None:
    name = platform.lower()
    prefixes = (
        ("cuda", "nvidia", "sm"),
        ("hygon", "hip", "dcu", "dtk"),
        ("ascend", "npu"),
    )
    for backend, names in zip(BACKENDS, prefixes, strict=True):
        if name.startswith(names):
            return backend
    return None


@agent_function
def get_backend(language: str, platform: str = "") -> Backend:
    """Resolve CUDA, Hygon HIP, or AscendC metadata without loading GPU libraries.

    Python requires an explicit accelerator platform. The returned Backend provides
    raw_source, raw_abi, and skill_name for native adapters and bundle instructions.
    Conflicting language/platform values raise ValueError.
    """
    target = platform_backend(platform)
    if language == "python":
        if target is None:
            raise ValueError("Python bundles require an explicit supported platform")
        return target
    for backend in BACKENDS:
        if language != backend.language:
            continue
        if target is not None and target is not backend:
            raise ValueError(
                f"language {language!r} conflicts with platform {platform!r}"
            )
        return backend
    raise ValueError(f"unsupported kernel language {language!r}")


