def tensor_values(problem: ProblemSpec, role: ValueRole) -> tuple[ABIValue, ...]:
    values = problem.values(role)
    if any(problem.definition[role][value.name]["shape"] is None for value in values):
        raise TypeError("tensor entries do not support scalar arguments or outputs")
    return values


def check_tensor(
    value: Any,
    spec: ABIValue,
    role: str,
    stride: tuple[int, ...] | None = None,
    *,
    backend: Backend,
) -> torch.Tensor:
    tensor = require_tensor(value, f"ABI {role} {spec.name!r}", backend)
    if tensor.dtype != tensor_dtype(spec.dtype):
        raise ValueError(f"ABI {role} {spec.name!r} has the wrong dtype")
    if tuple(tensor.shape) != spec.shape:
        raise ValueError(f"ABI {role} {spec.name!r} has the wrong shape")
    if stride is not None and tuple(tensor.stride()) != tuple(stride):
        raise ValueError(f"ABI {role} {spec.name!r} has the wrong stride")
    return tensor


def allocate(
    spec: ABIValue,
    device: torch.device,
    stride: tuple[int, ...] | None = None,
) -> torch.Tensor:
    import torch

    shape = fixed_shape(spec)
    if stride is None:
        return torch.empty(shape, dtype=tensor_dtype(spec.dtype), device=device)
    return torch.empty_strided(
        shape,
        tuple(int(value) for value in stride),
        dtype=tensor_dtype(spec.dtype),
        device=device,
    )


def fixed_shape(spec: ABIValue) -> tuple[int, ...]:
    if any(isinstance(value, str) for value in spec.shape):
        raise ValueError(f"output {spec.name!r} must have a fixed shape")
    return tuple(int(value) for value in spec.shape)


def tensor_dtype(value: str | None) -> torch.dtype:
    import torch

    if value is None:
        raise ValueError("ABI values require a dtype")
    name = value.lower().removeprefix("torch.")
    try:
        return getattr(torch, DTYPE_ALIASES[name])
    except KeyError as exc:
        raise ValueError(f"unsupported tensor dtype {value!r}") from exc


def require_tensor(value: Any, label: str, backend: Backend) -> torch.Tensor:
    torch = backend.torch()
    if not isinstance(value, torch.Tensor):
        raise TypeError(f"{label} must be a torch.Tensor")
    if value.device.type != backend.device_type:
        raise ValueError(f"{label} must be on {backend.device_type}")
    backend.validate_tensor(value)
    return value

class DeviceEventTimer:
    """Measure a HIP/NPU stream interval, including gaps between device work."""

    def __init__(self, backend: Backend, policy: TimingPolicy | None = None):
        if backend.timing_backend not in _EVENT_BACKENDS:
            raise ValueError("CUDA requires strict CUPTI timing")
        self.backend = backend
        self.policy = policy or TimingPolicy(cold_l2=False)
        if self.policy.cold_l2:
            raise ValueError("cold_l2 is unsupported by HIP/NPU event timing")

    def measure(self, fn: Callable[..., Any], *, args: tuple[Any, ...] = ()):
        if not callable(fn):
            raise TypeError("fn must be callable")
        runtime = self.backend.runtime()
        torch = self.backend.torch()
        device = next(
            (value.device for value in args if hasattr(value, "device")), None
        )
        if device is None:
            device = self.backend.device()
        trials = []
        with runtime.device(device), torch.inference_mode():
            stream = runtime.current_stream(device)
            for _ in range(self.policy.trials):
                for _ in range(self.policy.warmup):
                    fn(*args)
                runtime.synchronize(device)

                # Allocate events before recording; time only the current stream.
                events = [
                    (
                        runtime.Event(enable_timing=True),
                        runtime.Event(enable_timing=True),
                    )
                    for _ in range(self.policy.repeat)
                ]
                samples = []
                for start, end in events:
                    start.record(stream)
                    output = fn(*args)
                    end.record(stream)
                    end.synchronize()
                    samples.append(start.elapsed_time(end))
                    del output
                trials.append(validated_samples(samples))

        return TimingResult(
            samples_ms=tuple(trials),
            median_ms=float(statistics.median(map(statistics.median, trials))),
            backend_used=self.backend.timing_backend,
            details={
                "policy": self.policy.to_dict(),
                "scope": _EVENT_SCOPE,
                "device_type": self.backend.device_type,
            },
        )


def timing_policy(backend: Backend) -> TimingPolicy:
    return TimingPolicy(cold_l2=backend.timing_backend == _CUPTI_BACKEND)


def make_timer(backend: Backend, policy: TimingPolicy) -> KernelTimer:
    if backend.timing_backend == _CUPTI_BACKEND:
        return FlashInferCuptiTimer(policy)
    return DeviceEventTimer(backend, policy)

