import json, numpy as np
with open('work/problems/inputs/top_p.safetensors','rb') as f:
    n=int.from_bytes(f.read(8),'little'); hdr=json.loads(f.read(n)); data=f.read()
F=np.frombuffer(data,dtype='<f4',count=32*128256,offset=0).reshape(32,128256)
P=F.astype(np.float64)
V=128256; TP=0.9
cut_ref=[]; 
for r in range(32):
    s=np.sort(P[r])[::-1]; c=np.cumsum(s); k=int(np.searchsorted(c,TP,side='left')); cut_ref.append(s[k])
cut_ref=np.array(cut_ref)

def evalS(row,t): return float(row[row>=t].sum())

def ftok(x):  # float -> key (uint32)
    return np.frombuffer(np.float32(x).tobytes(),dtype=np.uint32)[0]
def ktof(k): return float(np.frombuffer(np.uint32(k).tobytes(),dtype=np.float32)[0])

def run(r, model='quad_logt', verbose=False):
    row=P[r]; npass=0
    tilemax=row[:4096].max()
    pts=[]  # (t, S)
    for j in range(5):
        t=tilemax*2.0**(-4*j); pts.append((t,evalS(row,t))); npass+=1
    lo_key=np.uint32(0); hi_key=np.uint32(ftok(1.0))
    lo_sum=None; hi_sum=None
    for it in range(6):
        # bracket from evaluated points
        lo=None; hi=None
        for t,s in pts:
            if s>=TP:
                if lo is None or t>lo[0]: lo=(t,s)
            else:
                if hi is None or t<hi[0]: hi=(t,s)
        if lo is None or hi is None:
            tpred=tilemax*2.0**(-2-2*it)
        else:
            x=np.log(np.array([p[0] for p in pts])); y=np.array([p[1] for p in pts])
            # use points closest to crossing
            idx=np.argsort(np.abs(y-TP))[:4]
            x=x[idx]; y=y[idx]; o=np.argsort(x); x=x[o]; y=y[o]
            if model=='quad_logt' and len(x)>=3:
                co=np.polyfit(x,y,2)
                A,B,C=co[0],co[1],co[2]-TP
                disc=B*B-4*A*C
                if disc<0: tpred=np.sqrt(lo[0]*hi[0])
                else:
                    rr=[(-B+np.sqrt(disc))/(2*A),(-B-np.sqrt(disc))/(2*A)]
                    rr=[v for v in rr if np.log(lo[0])<v<np.log(hi[0])]
                    tpred=float(np.exp(rr[0])) if rr else float(np.sqrt(lo[0]*hi[0]))
            elif model=='secant_log' and len(x)>=2:
                # linear in log t
                sl=(y[-1]-y[0])/(x[-1]-x[0]); tpred=float(np.exp(x[-1]+(TP-y[-1])/sl))
            elif model=='powerlaw' and len(x)>=2:
                sl=(np.log(y[-1])-np.log(y[0]))/(x[-1]-x[0]); tpred=float(np.exp(x[-1]+(np.log(TP)-np.log(y[-1]))/sl))
            else:
                tpred=float(np.sqrt(lo[0]*hi[0]))
            tpred=min(max(tpred, lo[0]*1.0000001), hi[0]*0.9999999)
        s=evalS(row,tpred); npass+=1; pts.append((tpred,s))
        relerr=abs(tpred-cut_ref[r])/cut_ref[r]
        if verbose: print(f'   it{it}: t={tpred:.6e} S={s:.9f} relerr={relerr:.2e}')
        if relerr < 3e-7: break
    # final bisection in key space
    lo=None; hi=None
    for t,s in pts:
        if s>=TP:
            if lo is None or t>lo[0]: lo=(t,s)
        else:
            if hi is None or t<hi[0]: hi=(t,s)
    lk=np.uint32(ftok(np.float32(lo[0]))); hk=np.uint32(ftok(np.float32(hi[0])))
    bis=0
    while hk-lk>1:
        mid=np.uint32(lk+(hk-lk)//2); t=ktof(mid)
        s=evalS(row,t); npass+=1; bis+=1
        if s>=TP: lk=mid
        else: hk=mid
    ans=ktof(lk)
    return npass, bis, ans==cut_ref[r], lo[0], hi[0]

for model in ['quad_logt','secant_log','powerlaw']:
    tot=0; bis_tot=0; ok=0
    for r in range(32):
        n,b,good,lo,hi=run(r,model)
        tot+=n; bis_tot+=b; ok+=good
    print(f'{model}: avg passes={tot/32:.1f} (avg bisection={bis_tot/32:.1f}) exact={ok}/32')
n,b,good,lo,hi=run(0,'quad_logt',verbose=True)
print('row0:',n,b,good,lo,hi,cut_ref[0])
