import json, numpy as np
with open('work/problems/inputs/top_p.safetensors','rb') as f:
    n=int.from_bytes(f.read(8),'little'); hdr=json.loads(f.read(n)); data=f.read()
F=np.frombuffer(data,dtype='<f4',count=32*128256,offset=0).reshape(32,128256)
P=F.astype(np.float64); TP=0.9
def refcut(row):
    s=np.sort(row)[::-1]; c=np.cumsum(s); k=int(np.searchsorted(c,TP,side='left')); return s[k]
def S(row,t): return float(row[row>=t].sum())
def C(row,t): return int((row>=t).sum())

def solve(row, nnewton=4, delta=0.01, verbose=False, usecount=True):
    cut=refcut(row); tilemax=row[:4096].max()
    ev=0
    pts=[]
    for j in range(4):
        t=tilemax*2.0**(-4*j); pts.append((t,S(row,t))); ev+=1
    ulo=None; uhi=None
    for t,s in pts:
        if s>=TP:
            if ulo is None or t>ulo: ulo=t
        else:
            if uhi is None or t<uhi: uhi=t
    # initial guess: linear in log t between the straddling ladder points
    t=None
    if ulo is not None and uhi is not None:
        la,lb=np.log(ulo),np.log(uhi); sa,sb=S(row,ulo),S(row,uhi)
        t=float(np.exp(la+(TP-sa)*(lb-la)/(sb-sa)))
    elif ulo is not None: t=ulo*2.0
    else: t=uhi/2.0
    for it in range(nnewton):
        t=min(max(t, ulo*1.0000001 if ulo else t*0.5), uhi*0.9999999 if uhi else t*2)
        s0=S(row,t); s1=S(row,t*(1+delta)); ev+=2
        if s0>=TP: ulo=max(ulo or 0,t)
        else: uhi=min(uhi or 1e9,t)
        if s1>=TP:
            if ulo is None or t*(1+delta)>ulo: ulo=t*(1+delta)
        else:
            if uhi is None or t*(1+delta)<uhi: uhi=t*(1+delta)
        m=(s0-s1)/delta
        if m<=0: break
        tn=t*np.exp((TP-s0)/m)
        if verbose: print(f'  N{it}: rel={abs(t-cut)/cut:.2e} S={s0:.9f} slope={m:.4f} t={t:.6e} next_rel={abs(tn-cut)/cut:.2e} bracket_rel={(uhi-ulo)/ulo:.2e}')
        t=tn
        if abs(t-cut)/cut < 3e-8: break
    # finish: key bisection from bracket (ulo,uhi) with count early stop
    lk=np.frombuffer(np.float32(ulo).tobytes(),dtype=np.uint32)[0]
    hk=np.frombuffer(np.float32(uhi).tobytes(),dtype=np.uint32)[0]
    nlo=C(row,ulo); nhi=C(row,uhi); bis=0
    while hk-lk>1:
        mid=np.uint32(lk+(hk-lk)//2); tt=float(np.frombuffer(mid.tobytes(),dtype=np.float32)[0])
        s=S(row,tt); cn=C(row,tt); bis+=1; ev+=1
        if s>=TP: lk,nlo=mid,cn
        else: hk,nhi=mid,cn
        if usecount and nlo==nhi: break
    ans=float(np.frombuffer(np.uint32(lk).tobytes(),dtype=np.float32)[0])
    return ev,bis,ans==cut

for nnewton in (3,4,5,6):
  for delta in (0.005,0.01,0.03):
    te=0;tb=0;ok=0
    for r in range(32):
        ev,bis,g=solve(P[r],nnewton,delta)
        te+=ev;tb+=bis;ok+=g
    print(f'newton={nnewton} delta={delta}: evals={te/32:.1f} bis={tb/32:.1f} total={(te+tb)/32:.1f} exact={ok}/32')
print()
print('trace row0:'); solve(P[0],5,0.01,verbose=True)
