def ref(p, t):
    ordered = torch.sort(p, dim=-1, descending=True, stable=True).values
    cum = ordered.to(torch.float64).cumsum(dim=-1)
    b = torch.searchsorted(cum, t.to(torch.float64).unsqueeze(-1), right=False).clamp_max(p.shape[-1]-1)
    cut = ordered.gather(-1, b)
    ret = torch.where(p >= cut, p, 0).to(torch.float64)
    return (ret / ret.sum(dim=-1, keepdim=True)).to(p.dtype)

