    sums = a.sum(dim=-1)
    print(f\"  {tag}: support ok {ok} sum [{float(sums.min()):.4f},{float(sums.max()):.4f}]\", flush=True)
    return ok

# correctness of mode 0 / 32 iters
m.kernel(probs, tp, out, 32, 0); torch.npu.synchronize(); check(\"mode0/32\")

