    torch.npu.synchronize()
    ts = []
    for _ in range(reps):
        e0.record(); m.kernel(probs, tp, out, iters, mode); e1.record(); e1.synchronize()
        ts.append(e0.elapsed_time(e1))
    return float(np.median(ts)), float(min(ts))

for mode, name in [(0,\"kahan\"),(1,\"plain\"),(2,\"countonly\"),(3,\"stream\"),(4,\"reducesum\")]:
