#include <torch/extension.h>
#include <c10/core/DeviceGuard.h>
#include <vector>
#include \"torch_npu/csrc/core/npu/NPUStream.h\"
#include \"acl/acl.h\"
#include \"ascendc/basic_api/kernel_operator.h\"
using namespace AscendC;

constexpr int32_t kLanes = 4096;

template <int32_t TILE>
class Bench {
public:
    __aicore__ inline void Init(GM_ADDR p, uint32_t cols, uint32_t mode, uint32_t iters)
    {
        row = GetBlockIdx(); this->cols = cols; this->mode = (int32_t)mode; this->iters = (int32_t)iters;
        nTiles = (int32_t)((cols + TILE - 1) / TILE);
        xGm.SetGlobalBuffer((__gm__ float *)p + (uint64_t)row * cols, cols);
        pipe.InitBuffer(inQ, 2, TILE * sizeof(float));
        pipe.InitBuffer(accBuf, kLanes * sizeof(float));
        pipe.InitBuffer(t1Buf, kLanes * sizeof(float));
        pipe.InitBuffer(zeroBuf, kLanes * sizeof(float));
        pipe.InitBuffer(maskBuf, TILE / 8 + 64);
    }
    __aicore__ inline void Run()
    {
        LocalTensor<float> acc = accBuf.Get<float>();
        LocalTensor<float> t1 = t1Buf.Get<float>();
        LocalTensor<float> zero = zeroBuf.Get<float>();
        LocalTensor<uint8_t> mask = maskBuf.Get<uint8_t>();
        Duplicate(acc, (float)0, kLanes);
        Duplicate(zero, (float)0, kLanes);
        PipeBarrier<PIPE_ALL>();
        constexpr int32_t kSub = TILE / kLanes;
        for (int32_t it = 0; it < iters; ++it) {
            for (int32_t tile = 0; tile < nTiles; ++tile) {
                int32_t off = tile * TILE;
                int32_t cnt = cols - off;
                if (cnt > TILE) cnt = TILE;
                LocalTensor<float> x = inQ.AllocTensor<float>();
                DataCopy(x, xGm[off], cnt);
                inQ.EnQue(x);
                x = inQ.DeQue<float>();
                for (int32_t h = 0; h < kSub; ++h) {
                    int32_t c = cnt - h * kLanes;
                    if (c > kLanes) c = kLanes;
                    if (c <= 0) break;
                    if (mode == 0) {
                        Add(acc, acc, x[h * kLanes], (uint32_t)c);
                    } else {
                        Compares(mask, x[h * kLanes], 1e-6f, CMPMODE::GE, (uint32_t)c);
                        Select(t1, mask, x[h * kLanes], zero, SELMODE::VSEL_TENSOR_TENSOR_MODE, (uint32_t)c);
                        Add(acc, acc, t1, (uint32_t)c);
                    }
                }
                inQ.FreeTensor(x);
            }
        }
        if (acc.GetValue(0) < -1.0f) { xGm.SetValue(0, 1.0f); }
    }
private:
    TPipe pipe;
    TQue<TPosition::VECIN, 2> inQ;
    TBuf<TPosition::VECCALC> accBuf, t1Buf, zeroBuf, maskBuf;
    GlobalTensor<float> xGm;
    int32_t row, cols, mode, iters, nTiles;
};

__global__ __aicore__ void bench_kernel(GM_ADDR p, uint32_t rows, uint32_t cols, uint32_t mode, uint32_t iters)
{
    if (mode < 3) {
        Bench<4096> op; op.Init(p, cols, mode, iters); op.Run();
    } else if (mode < 6) {
        Bench<8192> op; op.Init(p, cols, mode, iters); op.Run();
    } else {
        Bench<16384> op; op.Init(p, cols, mode, iters); op.Run();
    }
}

void kernel(const torch::Tensor &probs, int64_t mode, int64_t iters)
{
    const c10::DeviceGuard guard(probs.device());
    aclrtStream stream = c10_npu::getCurrentNPUStream(probs.get_device()).stream(true);
    bench_kernel<<<(uint32_t)probs.size(0), nullptr, stream>>>(
        (uint8_t *)probs.data_ptr<float>(), (uint32_t)probs.size(0), (uint32_t)probs.size(1),
        (uint32_t)mode, (uint32_t)iters);
}
PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) { module.def(\"kernel\", &kernel); }
